/*
 * Design tokens ported verbatim from opencode's `@opencode/ui`
 * (packages/ui/src/styles/tokens + styles/theme.css), so the components in
 * src/components/ui can be a 1:1 port of their visuals.
 *
 * Layer 1  typography   font stacks, sizes, weights, leading, tracking
 * Layer 2  --v2-*       primitives + semantic layers (light in :root, 97 overrides in dark)
 * Layer 3  --oc-*       the console's own app aliases
 * Layer 4  @theme       what becomes Tailwind utilities (bottom of this file)
 *
 * Dark mode is attribute driven: `[data-color-scheme="dark"]` on <html>, set
 * before the first paint by the script in index.html. Component stylesheets
 * (like ui/button.css) read that attribute too, so keep it as the single
 * switch — a bare `prefers-color-scheme` block would flip the tokens without
 * flipping those components.
 */

:root {
  color-scheme: light;

  /* 0 typography */
  --font-family-sans: "Inter Variable", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-family-sans--font-feature-settings: normal;
  --font-family-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --font-family-mono--font-feature-settings: normal;

  --font-size-small: 13px;
  --font-size-base: 14px;
  --font-size-large: 16px;
  --font-size-x-large: 20px;
  --font-weight-regular: 440;
  --font-weight-medium: 530;
  --font-weight-bold: 670;
  --line-height-tight: 12px;
  --line-height-compact: 16px;
  --line-height-base: 20px;
  --line-height-normal: 130%;
  --line-height-large: 150%;
  --line-height-x-large: 180%;
  --line-height-2x-large: 200%;
  --letter-spacing-normal: 0;
  --letter-spacing-tight: -0.1599999964237213;
  --letter-spacing-tightest: -0.3199999928474426;
  --paragraph-spacing-base: 0;

  /* 1 palette · neutral */
  --v2-grey-50: #fff;
  --v2-grey-100: #fafafa;
  --v2-grey-200: #f2f2f2;
  --v2-grey-300: #eee;
  --v2-grey-400: #dbdbdb;
  --v2-grey-500: #aeaeae;
  --v2-grey-600: gray;
  --v2-grey-700: #5c5c5c;
  --v2-grey-800: #3a3a3a;
  --v2-grey-900: #2e2e2e;
  --v2-grey-1000: #242424;
  --v2-grey-1100: #161616;
  --v2-grey-1200: #080808;

  /* 2 palette · accents */
  --v2-blue-100: #f5f8ff;
  --v2-blue-200: #ecf1fe;
  --v2-blue-300: #c3d4fd;
  --v2-blue-400: #a2bcff;
  --v2-blue-500: #7698fd;
  --v2-blue-600: #3b5cf6;
  --v2-blue-700: #0b34f4;
  --v2-blue-800: #3250df;
  --v2-blue-900: #2c47c8;
  --v2-blue-1000: #263fa9;
  --v2-blue-1100: #22388f;
  --v2-blue-1200: #021945;
  --v2-cyan-100: #e2f7fb;
  --v2-cyan-200: #c4edf4;
  --v2-cyan-300: #a3e4ef;
  --v2-cyan-400: #65d9eb;
  --v2-cyan-500: #00c5df;
  --v2-cyan-600: #00abcf;
  --v2-cyan-700: #0096b8;
  --v2-cyan-800: #007d9b;
  --v2-cyan-900: #006c85;
  --v2-cyan-1000: #005a6e;
  --v2-cyan-1100: #004756;
  --v2-cyan-1200: #00353f;
  --v2-green-100: #e7f9ea;
  --v2-green-200: #d0f0d5;
  --v2-green-300: #b8e9c1;
  --v2-green-400: #96e3a6;
  --v2-green-500: #6bd586;
  --v2-green-600: #49c970;
  --v2-green-700: #2eaf5a;
  --v2-green-800: #198b43;
  --v2-green-900: #1d783c;
  --v2-green-1000: #196130;
  --v2-green-1100: #164c26;
  --v2-green-1200: #14361d;
  --v2-orange-100: #fdf2ed;
  --v2-orange-200: #ffe7dc;
  --v2-orange-300: #ffd8c6;
  --v2-orange-400: #ffc1a4;
  --v2-orange-500: #ffa478;
  --v2-orange-600: #ff8648;
  --v2-orange-700: #ee7330;
  --v2-orange-800: #d16427;
  --v2-orange-900: #b35624;
  --v2-orange-1000: #954c27;
  --v2-orange-1100: #723d22;
  --v2-orange-1200: #5a2c14;
  --v2-pink-100: #fdecf3;
  --v2-pink-200: #f7d5e4;
  --v2-pink-300: #fabcd8;
  --v2-pink-400: #f799c6;
  --v2-pink-500: #f26cb2;
  --v2-pink-600: #f64aab;
  --v2-pink-700: #e4429e;
  --v2-pink-800: #c83d8b;
  --v2-pink-900: #aa3576;
  --v2-pink-1000: #8c2d61;
  --v2-pink-1100: #6f284f;
  --v2-pink-1200: #5c1d3f;
  --v2-purple-100: #ebecfe;
  --v2-purple-200: #d5d5fc;
  --v2-purple-300: #b9b8f5;
  --v2-purple-400: #9e99f7;
  --v2-purple-500: #8271f8;
  --v2-purple-600: #7152f4;
  --v2-purple-700: #623be2;
  --v2-purple-800: #5230c2;
  --v2-purple-900: #442aa1;
  --v2-purple-1000: #361f83;
  --v2-purple-1100: #2b1b6a;
  --v2-purple-1200: #221358;
  --v2-red-100: #fceceb;
  --v2-red-200: #f6d5d3;
  --v2-red-300: #f2bbb7;
  --v2-red-400: #f29b96;
  --v2-red-500: #f17471;
  --v2-red-600: #f1484f;
  --v2-red-700: #d92e3c;
  --v2-red-800: #b82d35;
  --v2-red-900: #97252b;
  --v2-red-1000: #7a1f23;
  --v2-red-1100: #5f1a1c;
  --v2-red-1200: #461516;
  --v2-yellow-100: #fefaec;
  --v2-yellow-200: #fcefd0;
  --v2-yellow-300: #f7e5b5;
  --v2-yellow-400: #f3da9b;
  --v2-yellow-500: #f2cf76;
  --v2-yellow-600: #f6c251;
  --v2-yellow-700: #e7af36;
  --v2-yellow-800: #cb9f34;
  --v2-yellow-900: #ac8833;
  --v2-yellow-1000: #8e7231;
  --v2-yellow-1100: #68552b;
  --v2-yellow-1200: #4b4025;

  /* 3 alpha overlays */
  --v2-alpha-dark-0: #0000;
  --v2-alpha-dark-2: #00000005;
  --v2-alpha-dark-4: #0000000a;
  --v2-alpha-dark-6: #0000000f;
  --v2-alpha-dark-8: #00000014;
  --v2-alpha-dark-10: #0000001a;
  --v2-alpha-dark-12: #0000001f;
  --v2-alpha-dark-14: #00000024;
  --v2-alpha-dark-16: #00000029;
  --v2-alpha-dark-20: #0003;
  --v2-alpha-dark-24: #0000003d;
  --v2-alpha-dark-30: #0000004d;
  --v2-alpha-dark-40: #0006;
  --v2-alpha-dark-50: #00000080;
  --v2-alpha-dark-60: #0009;
  --v2-alpha-dark-70: #000000b2;
  --v2-alpha-dark-80: #000c;
  --v2-alpha-dark-90: #000000e5;
  --v2-alpha-dark-100: #000;
  --v2-alpha-light-0: #fff0;
  --v2-alpha-light-2: #ffffff05;
  --v2-alpha-light-4: #ffffff0a;
  --v2-alpha-light-6: #ffffff0f;
  --v2-alpha-light-8: #ffffff14;
  --v2-alpha-light-10: #ffffff1a;
  --v2-alpha-light-12: #ffffff1f;
  --v2-alpha-light-14: #ffffff24;
  --v2-alpha-light-16: #ffffff29;
  --v2-alpha-light-20: #fff3;
  --v2-alpha-light-24: #ffffff3d;
  --v2-alpha-light-30: #ffffff4d;
  --v2-alpha-light-40: #fff6;
  --v2-alpha-light-50: #ffffff80;
  --v2-alpha-light-60: #fff9;
  --v2-alpha-light-70: #ffffffb2;
  --v2-alpha-light-80: #fffc;
  --v2-alpha-light-90: #ffffffe5;
  --v2-alpha-light-100: #fff;

  /* 4 semantic · agent */
  --v2-agent-build-background: #ecf1fe1a;
  --v2-agent-build-border: #2c47c81a;
  --v2-agent-build-solid: var(--v2-blue-800);
  --v2-agent-explore-background: #fefaec1a;
  --v2-agent-explore-border: #cb9f3433;
  --v2-agent-explore-solid: var(--v2-yellow-900);
  --v2-agent-plan-background: #fdecf31a;
  --v2-agent-plan-border: #c83d8b33;
  --v2-agent-plan-solid: var(--v2-pink-800);
  --v2-agent-review-solid: var(--v2-green-800);
  --v2-agent-writer-solid: var(--v2-purple-700);

  /* 4 semantic · avatar */
  --v2-avatar-bg-blue: #3250df;
  --v2-avatar-bg-cyan: #0096b8;
  --v2-avatar-bg-gray: #5c5c5c;
  --v2-avatar-bg-green: #2eaf5a;
  --v2-avatar-bg-orange: #ee7330;
  --v2-avatar-bg-pink: #e4429e;
  --v2-avatar-bg-purple: #623be2;
  --v2-avatar-bg-red: #d92e3c;
  --v2-avatar-bg-yellow: #e7af36;
  --v2-avatar-border-blue: #2c47c8;
  --v2-avatar-border-cyan: #007d9b;
  --v2-avatar-border-gray: #3a3a3a;
  --v2-avatar-border-green: #198b43;
  --v2-avatar-border-orange: #d16427;
  --v2-avatar-border-pink: #c83d8b;
  --v2-avatar-border-purple: #5230c2;
  --v2-avatar-border-red: #b82d35;
  --v2-avatar-border-yellow: #cb9f34;
  --v2-avatar-fg: #fff;

  /* 4 semantic · background */
  --v2-background-bg-accent: var(--v2-blue-600);
  --v2-background-bg-base: var(--v2-grey-50);
  --v2-background-bg-button-neutral: var(--v2-grey-50);
  --v2-background-bg-code-path: var(--v2-cyan-100);
  --v2-background-bg-contrast: var(--v2-grey-1000);
  --v2-background-bg-deep: var(--v2-grey-100);
  --v2-background-bg-icon-button-contrast: var(--v2-background-bg-contrast);
  --v2-background-bg-inverse: var(--v2-grey-1100);
  --v2-background-bg-layer-01: var(--v2-grey-100);
  --v2-background-bg-layer-02: var(--v2-grey-200);
  --v2-background-bg-layer-03: var(--v2-grey-300);
  --v2-background-bg-layer-04: var(--v2-grey-400);

  /* 4 semantic · border */
  --v2-border-border-base: var(--v2-alpha-dark-10);
  --v2-border-border-focus: var(--v2-blue-500);
  --v2-border-border-inverse: var(--v2-grey-1000);
  --v2-border-border-muted: var(--v2-alpha-dark-8);
  --v2-border-border-strong: var(--v2-alpha-dark-20);

  /* 4 semantic · icon */
  --v2-icon-icon-accent: var(--v2-blue-600);
  --v2-icon-icon-accent-hover: var(--v2-blue-700);
  --v2-icon-icon-base: var(--v2-grey-800);
  --v2-icon-icon-contrast: var(--v2-grey-100);
  --v2-icon-icon-faint: var(--v2-grey-500);
  --v2-icon-icon-inverse: var(--v2-grey-50);
  --v2-icon-icon-muted: var(--v2-grey-600);

  /* 4 semantic · illustration */
  --v2-illustration-illustration-layer-01: var(--v2-grey-300);
  --v2-illustration-illustration-layer-02: var(--v2-grey-400);
  --v2-illustration-illustration-layer-03: var(--v2-grey-500);

  /* 4 semantic · overlay */
  --v2-overlay-gradient-depth-overlay-depth-bot: var(--v2-alpha-light-0);
  --v2-overlay-gradient-depth-overlay-depth-top: var(--v2-alpha-light-100);
  --v2-overlay-simple-overlay-contrast-hover: var(--v2-alpha-light-12);
  --v2-overlay-simple-overlay-contrast-pressed: var(--v2-alpha-light-24);
  --v2-overlay-simple-overlay-hover: var(--v2-alpha-dark-4);
  --v2-overlay-simple-overlay-pressed: var(--v2-alpha-dark-8);
  --v2-overlay-simple-overlay-scrim: var(--v2-alpha-dark-40);
  --v2-overlay-simple-tab-active-scrim: #fafafa00;
  --v2-overlay-simple-tab-hover-scrim: #eee0;
  --v2-overlay-simple-tab-scrim: #fafafa00;

  /* 4 semantic · state */
  --v2-state-bg-danger: var(--v2-red-100);
  --v2-state-bg-info: var(--v2-blue-200);
  --v2-state-bg-success: var(--v2-green-100);
  --v2-state-bg-warning: var(--v2-yellow-100);
  --v2-state-border-danger: var(--v2-red-300);
  --v2-state-border-info: var(--v2-blue-300);
  --v2-state-border-success: var(--v2-green-300);
  --v2-state-border-warning: var(--v2-yellow-300);
  --v2-state-fg-danger: var(--v2-red-800);
  --v2-state-fg-info: var(--v2-blue-800);
  --v2-state-fg-success: var(--v2-green-800);
  --v2-state-fg-warning: var(--v2-yellow-800);

  /* 4 semantic · text */
  --v2-text-text-accent: var(--v2-blue-600);
  --v2-text-text-accent-hover: var(--v2-blue-700);
  --v2-text-text-base: var(--v2-grey-1100);
  --v2-text-text-code-accent: var(--v2-blue-900);
  --v2-text-text-code-path: var(--v2-blue-900);
  --v2-text-text-contrast: var(--v2-grey-50);
  --v2-text-text-faint: var(--v2-grey-600);
  --v2-text-text-inverse: var(--v2-grey-50);
  --v2-text-text-muted: var(--v2-grey-700);

  /* 5 elevation */
  --v2-elevation-button-contrast: 0px 1px 1.5px 0px var(--v2-alpha-dark-20), 0px 0px 0px .5px var(--v2-grey-800), inset 0px 1px 2px 0px var(--v2-alpha-light-14), inset 0px -1px 2px 0px var(--v2-alpha-dark-6), 0px 0px 0px 0px var(--v2-alpha-dark-0);
  --v2-elevation-button-neutral: 0px 1px 1.5px 0px var(--v2-alpha-dark-10), 0px 0px 0px .5px var(--v2-alpha-dark-14), 0px 0px 0px 0px var(--v2-alpha-dark-0);
  --v2-elevation-elements: 0px .5px .5px 0px var(--v2-alpha-dark-40);
  --v2-elevation-floating: 0px 8px 16px 0px var(--v2-alpha-dark-4), 0px 4px 8px 0px var(--v2-alpha-dark-8), 0px 0px 0px .5px var(--v2-alpha-dark-12), 0px 0px 0px 0px var(--v2-alpha-dark-0);
  --v2-elevation-input: 0px 1px 1.5px 0px var(--v2-alpha-dark-10), 0px 0px 0px .5px var(--v2-alpha-dark-14), 0px 0px 0px 0px var(--v2-alpha-dark-0);
  --v2-elevation-overlay: 0px 16px 32px 0px var(--v2-alpha-dark-4), 0px 8px 16px 0px var(--v2-alpha-dark-8), 0px 0px 0px .5px var(--v2-alpha-dark-12), 0px 0px 0px 0px var(--v2-alpha-dark-0);
  --v2-elevation-raised: 0px 2px 4px 0px var(--v2-alpha-dark-4), 0px 1px 2px -1px var(--v2-alpha-dark-8), 0px 0px 0px .5px var(--v2-alpha-dark-12), 0px 0px 0px 0px var(--v2-alpha-dark-0);
  --v2-elevation-switch-off: inset 0px 1px 1px 0px var(--v2-alpha-dark-8), inset 0px .5px .5px 0px var(--v2-alpha-dark-8), inset 0px 0px 0px .5px var(--v2-alpha-dark-10);
  --v2-elevation-switch-on: inset 0px 2px 2px 0px var(--v2-alpha-dark-10), inset 0px 1px 1px 0px var(--v2-alpha-dark-10), inset 0px 0px 0px .5px var(--v2-alpha-dark-20);

  /* 6 typography */
  --font-family-text: var(--font-family-sans);
  --v2-font-family-code: var(--font-family-mono);
  --v2-font-family-sans: var(--font-family-sans);

  /* 7 app aliases (the console's --oc-* layer) */
  --oc-bg: var(--v2-background-bg-base);
  --oc-surface: var(--v2-background-bg-layer-01);
  --oc-elevated: var(--v2-background-bg-base);
  --oc-text: var(--v2-text-text-base);
  --oc-text-secondary: var(--v2-text-text-muted);
  --oc-text-muted: var(--v2-text-text-faint);
  --oc-text-disabled: var(--v2-grey-500);
  --oc-accent: var(--v2-text-text-accent);
  --oc-accent-hover: var(--v2-text-text-accent-hover);
  --oc-border: var(--v2-border-border-base);
  --oc-border-muted: var(--v2-border-border-muted);
  --oc-success: var(--v2-state-fg-success);
  --oc-warning: var(--v2-state-fg-warning);
  --oc-danger: var(--v2-state-fg-danger);
  --oc-font-mono: var(--font-family-mono);

  /* console header hover overlay (measured: #ffffff1a) */
  --console-nav-hover: #ffffff1a;
}

/* Explicit light scheme, so a region can opt back out of a dark ancestor
   (opencode ships the same block). The values mirror :root above. */
[data-color-scheme="light"] {
  color-scheme: light;

  --v2-background-bg-base: var(--v2-grey-50);
  --v2-background-bg-deep: var(--v2-grey-100);
  --v2-background-bg-layer-01: var(--v2-grey-100);
  --v2-background-bg-layer-02: var(--v2-grey-200);
  --v2-background-bg-layer-03: var(--v2-grey-300);
  --v2-background-bg-layer-04: var(--v2-grey-400);
  --v2-background-bg-inverse: var(--v2-grey-1100);
  --v2-background-bg-contrast: var(--v2-grey-1000);
  --v2-background-bg-icon-button-contrast: var(--v2-background-bg-contrast);
  --v2-background-bg-button-neutral: var(--v2-grey-50);
  --v2-background-bg-accent: var(--v2-blue-600);
  --v2-background-bg-code-path: var(--v2-cyan-100);

  --v2-text-text-base: var(--v2-grey-1100);
  --v2-text-text-muted: var(--v2-grey-700);
  --v2-text-text-faint: var(--v2-grey-600);
  --v2-text-text-inverse: var(--v2-grey-50);
  --v2-text-text-contrast: var(--v2-grey-50);
  --v2-text-text-accent: var(--v2-blue-600);
  --v2-text-text-accent-hover: var(--v2-blue-700);
  --v2-text-text-code-accent: var(--v2-blue-900);
  --v2-text-text-code-path: var(--v2-blue-900);

  --v2-icon-icon-base: var(--v2-grey-800);
  --v2-icon-icon-muted: var(--v2-grey-600);
  --v2-icon-icon-faint: var(--v2-grey-500);
  --v2-icon-icon-inverse: var(--v2-grey-50);
  --v2-icon-icon-contrast: var(--v2-grey-100);
  --v2-icon-icon-accent: var(--v2-blue-600);
  --v2-icon-icon-accent-hover: var(--v2-blue-700);

  --v2-border-border-muted: var(--v2-alpha-dark-8);
  --v2-border-border-base: var(--v2-alpha-dark-10);
  --v2-border-border-strong: var(--v2-alpha-dark-20);
  --v2-border-border-inverse: var(--v2-grey-1000);
  --v2-border-border-focus: var(--v2-blue-500);

  --v2-overlay-simple-overlay-hover: var(--v2-alpha-dark-4);
  --v2-overlay-simple-overlay-pressed: var(--v2-alpha-dark-8);
  --v2-overlay-simple-overlay-contrast-hover: var(--v2-alpha-light-12);
  --v2-overlay-simple-overlay-contrast-pressed: var(--v2-alpha-light-24);
  --v2-overlay-simple-overlay-scrim: var(--v2-alpha-dark-40);
  --v2-overlay-gradient-depth-overlay-depth-top: var(--v2-alpha-light-100);
  --v2-overlay-gradient-depth-overlay-depth-bot: var(--v2-alpha-light-0);
  --v2-overlay-simple-tab-active-scrim: #fafafa00;
  --v2-overlay-simple-tab-hover-scrim: #eeeeee00;
  --v2-overlay-simple-tab-scrim: #fafafa00;

  --v2-state-bg-success: var(--v2-green-100);
  --v2-state-fg-success: var(--v2-green-800);
  --v2-state-border-success: var(--v2-green-300);
  --v2-state-bg-warning: var(--v2-yellow-100);
  --v2-state-fg-warning: var(--v2-yellow-800);
  --v2-state-border-warning: var(--v2-yellow-300);
  --v2-state-bg-danger: var(--v2-red-100);
  --v2-state-fg-danger: var(--v2-red-800);
  --v2-state-border-danger: var(--v2-red-300);
  --v2-state-bg-info: var(--v2-blue-200);
  --v2-state-fg-info: var(--v2-blue-800);
  --v2-state-border-info: var(--v2-blue-300);

  --v2-agent-plan-solid: var(--v2-pink-800);
  --v2-agent-plan-border: rgba(200, 61, 139, 0.2);
  --v2-agent-plan-background: rgba(253, 236, 243, 0.1);
  --v2-agent-build-solid: var(--v2-blue-800);
  --v2-agent-build-border: rgba(44, 71, 200, 0.1);
  --v2-agent-build-background: rgba(236, 241, 254, 0.1);
